    private function challenge(array $row): array { return ['id'=>$row['id'],'user_id'=>$row['user_id'],'configuration'=>Database::decode($row['configuration']),'target_text'=>$row['target_text'],'starts_at'=>Database::iso($row['starts_at']),'deadline_at'=>Database::iso($row['deadline_at']),'expires_at'=>Database::iso($row['expires_at']),'server_now'=>Database::iso(Database::timestamp($this->now()))]; }
